CREATE OR REPLACE VIEW ANALYTICS.VW_MORTGAGE_ANALYTICS AS SELECT L.LOAN_ID,B.FIRST_NAME,B.LAST_NAME,L.LOAN_AMOUNT,L.CURRENT_UPB,L.INTEREST_RATE,L.LOAN_STATUS,I.INVESTOR_NAME,S.SERVICER_NAME,D.DAYS_PAST_DUE,D.RISK_LEVEL FROM CURATED.LOANS L JOIN CURATED.BORROWERS B ON L.BORROWER_ID=B.BORROWER_ID LEFT JOIN CURATED.INVESTORS I ON L.INVESTOR_ID=I.INVESTOR_ID LEFT JOIN CURATED.SERVICERS S ON L.SERVICER_ID=S.SERVICER_ID LEFT JOIN CURATED.DELINQUENCY D ON L.LOAN_ID=D.LOAN_ID;